import Foundation protocol LCAppModelDelegate { func closeNavigationView() func changeAppVisibility(app : LCAppModel) func jitLaunch(appName: String, classicMode: UInt) async func jitLaunch(withScript script: String, appName: String, classicMode: UInt) async func jitLaunch(withPID pid: Int, withScript script: String?, appName: String) async func showRunWhenMultitaskAlert() async -> Bool? } class LCAppModel: ObservableObject, Hashable { @Published var appInfo : LCAppInfo @Published var isAppRunning = false @Published var isSigningInProgress = false @Published var signProgress = 0.0 private var observer : NSKeyValueObservation? @Published var uiIsJITNeeded : Bool = false { didSet { appInfo.isJITNeeded = uiIsJITNeeded } } /// Per-app JIT enable — user toggles this on to use JIT for this app. /// When on, launching the app will go through the JIT path (pairing file + VPN). @Published var uiIsJITEnabled : Bool = false { didSet { appInfo.isJITEnabled = uiIsJITEnabled } } /// When on, launch waits for LocalDevVPN to connect before attaching JIT. @Published var uiWaitForVPN : Bool = false { didSet { appInfo.waitForVPN = uiWaitForVPN } } /// Path to the user’s pairing file (selected via document picker). @Published var uiPairingFilePath : String? = nil { didSet { appInfo.pairingFilePath = uiPairingFilePath } } @Published var uiHelperProcessesSupport: Bool = false { didSet { appInfo.helperProcessesSupport = uiHelperProcessesSupport } } @Published var uiClassicMode : Bool = false { didSet { appInfo.classicMode = uiClassicMode } } @Published var uiIsHidden : Bool = false @Published var uiIsLocked : Bool = false @Published var uiIsShared : Bool = false @Published var uiIsFavorite : Bool = false { didSet { appInfo.isFavorite = uiIsFavorite } } @Published var uiDefaultDataFolder : String? = nil @Published var uiContainers : [LCContainer] = [] @Published var uiSelectedContainer : LCContainer? = nil @Published var uiIs32bit : Bool = false @Published var uiIs32bitEmulator : Bool = false @Published var uiTweakFolder : String? = nil { didSet { appInfo.tweakFolder = uiTweakFolder } } @Published var uiDoSymlinkInbox : Bool = false { didSet { appInfo.doSymlinkInbox = uiDoSymlinkInbox } } @Published var uiUseLCBundleId : Bool = false { didSet { appInfo.doUseLCBundleId = uiUseLCBundleId } } @Published var uiFixFilePickerNew : Bool = false { didSet { appInfo.fixFilePickerNew = uiFixFilePickerNew } } @Published var uiFixLocalNotification : Bool = false { didSet { appInfo.fixLocalNotification = uiFixLocalNotification } } @Published var uiFixBackgroundTaskIdentifiers : Bool = false { didSet { appInfo.fixBackgroundTaskIdentifiers = uiFixBackgroundTaskIdentifiers } } @Published var uiHideLiveContainer : Bool = false { didSet { appInfo.hideLiveContainer = uiHideLiveContainer } } @Published var uiTweakLoaderInjectFailed : Bool = false @Published var uiDontInjectTweakLoader : Bool = false { didSet { appInfo.dontInjectTweakLoader = uiDontInjectTweakLoader } } @Published var uiDontLoadTweakLoader : Bool = false { didSet { appInfo.dontLoadTweakLoader = uiDontLoadTweakLoader } } @Published var uiOrientationLock : LCOrientationLock = .portrait { didSet { appInfo.orientationLock = uiOrientationLock } } @Published var uiSelectedLanguage : String = "" { didSet { appInfo.selectedLanguage = uiSelectedLanguage } } @Published var uiDontSign : Bool = false { didSet { appInfo.dontSign = uiDontSign } } @Published var jitLaunchScriptJs: String? = nil { didSet { appInfo.jitLaunchScriptJs = jitLaunchScriptJs } } @Published var uiSelected32BitEmulator : String = "" { didSet { appInfo.selected32BitEmulator = uiSelected32BitEmulator } } @Published var uiSpoofSDKVersion : Bool = false { didSet { appInfo.spoofSDKVersion = uiSpoofSDKVersion } } @Published var uiRemark : String = "" { didSet { appInfo.remark = uiRemark } } @Published var uiIsMultitaskModeSpecificed : MultitaskSpecified = .default { didSet { appInfo.multitaskSpecified = uiIsMultitaskModeSpecificed; } } public var bundleIdentifier: String { get { return appInfo.bundleIdentifier() ?? "?" } } public var version: String { get { return appInfo.version() ?? "?" } } public var displayName: String { get { return appInfo.displayName() ?? "?" } } public var shouldLaunchInMultitaskMode : Bool { get { if #available(iOS 16.0, *) { return uiIsMultitaskModeSpecificed == .yes || (uiIsMultitaskModeSpecificed == .default && UserDefaults.standard.bool(forKey: "LCLaunchInMultitaskMode")) } else { return false } } } @Published var supportedLanguages : [String]? = nil var delegate : LCAppModelDelegate? init(appInfo : LCAppInfo, delegate: LCAppModelDelegate? = nil) { self.appInfo = appInfo self.delegate = delegate if !appInfo.isLocked && appInfo.isHidden { appInfo.isLocked = true } self.uiIsJITNeeded = appInfo.isJITNeeded self.uiIsJITEnabled = appInfo.isJITEnabled self.uiWaitForVPN = appInfo.waitForVPN self.uiPairingFilePath = appInfo.pairingFilePath self.uiHelperProcessesSupport = appInfo.helperProcessesSupport self.uiClassicMode = appInfo.classicMode self.uiIsHidden = appInfo.isHidden self.uiIsLocked = appInfo.isLocked self.uiIsShared = appInfo.isShared self.uiIsFavorite = appInfo.isFavorite self.uiSelectedLanguage = appInfo.selectedLanguage ?? "" self.uiDefaultDataFolder = appInfo.dataUUID self.uiContainers = appInfo.containers self.uiTweakFolder = appInfo.tweakFolder self.uiDoSymlinkInbox = appInfo.doSymlinkInbox self.uiOrientationLock = appInfo.orientationLock self.uiIsMultitaskModeSpecificed = appInfo.multitaskSpecified self.uiUseLCBundleId = appInfo.doUseLCBundleId self.uiFixFilePickerNew = appInfo.fixFilePickerNew self.uiFixLocalNotification = appInfo.fixLocalNotification self.uiFixBackgroundTaskIdentifiers = appInfo.fixBackgroundTaskIdentifiers self.uiHideLiveContainer = appInfo.hideLiveContainer self.uiDontInjectTweakLoader = appInfo.dontInjectTweakLoader self.uiTweakLoaderInjectFailed = appInfo.info()["LCTweakLoaderCantInject"] as? Bool ?? false self.uiDontLoadTweakLoader = appInfo.dontLoadTweakLoader self.uiDontSign = appInfo.dontSign self.jitLaunchScriptJs = appInfo.jitLaunchScriptJs self.uiSelected32BitEmulator = appInfo.selected32BitEmulator ?? "" self.uiSpoofSDKVersion = appInfo.spoofSDKVersion self.uiRemark = appInfo.remark ?? "" self.uiIs32bit = appInfo.is32bit self.uiIs32bitEmulator = appInfo.is32bitEmulator for container in uiContainers { if container.folderName == uiDefaultDataFolder { self.uiSelectedContainer = container; break } } } static func == (lhs: LCAppModel, rhs: LCAppModel) -> Bool { return lhs === rhs } func hash(into hasher: inout Hasher) { hasher.combine(ObjectIdentifier(self)) } // You should let LCAppModel.runApp to decide whether to run in multitask mode, but you may override the multitask parameter if necessary func runApp(multitask: Bool? = nil, containerFolderName : String? = nil, bundleIdOverride : String? = nil, urlStr : String? = nil, forceJIT: Bool? = nil) async throws{ if isAppRunning { return } if uiContainers.isEmpty { let newName = NSUUID().uuidString let newContainer = LCContainer(folderName: newName, name: newName, isShared: uiIsShared) uiContainers.append(newContainer) if uiSelectedContainer == nil { uiSelectedContainer = newContainer; } appInfo.containers = uiContainers; newContainer.makeLCContainerInfoPlist(appIdentifier: appInfo.bundleIdentifier()!, keychainGroupId: Int.random(in: 0..<SharedModel.keychainAccessGroupCount)) appInfo.dataUUID = newName uiDefaultDataFolder = newName } if let containerFolderName { uiSelectedContainer = uiContainers.first { $0.folderName == containerFolderName } ?? uiSelectedContainer } let currentDataFolder = containerFolderName ?? uiSelectedContainer?.folderName let classicMode = appInfo.defaultClassicMode let multitask = classicMode == 0 ? (multitask ?? shouldLaunchInMultitaskMode) : false if MultitaskManager.isMultitasking() || multitask, let currentDataFolder { if await bringExistingMultitaskWindowIfNeeded(dataUUID: currentDataFolder, urlScheme: urlStr) { return } } if let fn = uiSelectedContainer?.folderName, var runningLC = LCSharedUtils.getContainerUsingLCScheme(withFolderName: fn) { runningLC = (runningLC as NSString).deletingPathExtension var openURLComp = URLComponents() openURLComp.scheme = runningLC if let urlStr { openURLComp.host = "open-url" openURLComp.queryItems = [ URLQueryItem(name: "url", value: Data(urlStr.utf8).base64EncodedString()) ] } if await UIApplication.shared.canOpenURL(openURLComp.url!) { await UIApplication.shared.open(openURLComp.url!) return } } if MultitaskManager.isMultitasking() && !multitask { if self.uiIsShared { var freeScheme: String? = nil LCUtils.forEachInstalledLC(isFree: true) { scheme, shouldBreak in freeScheme = scheme shouldBreak = true } if let freeScheme { LCUtils.appGroupUserDefault.set(freeScheme, forKey: "LCLaunchExtensionScheme") LCUtils.appGroupUserDefault.set(self.appInfo.relativeBundlePath, forKey: "LCLaunchExtensionBundleID") LCUtils.appGroupUserDefault.set(uiSelectedContainer?.folderName, forKey: "LCLaunchExtensionContainerName") if let urlStr { LCUtils.appGroupUserDefault.set(urlStr, forKey: "LCLaunchExtensionLaunchURL") } LCUtils.appGroupUserDefault.set(Date.now, forKey: "LCLaunchExtensionLaunchDate") var launchURLComp = URLComponents() launchURLComp.scheme = freeScheme launchURLComp.host = "livecontainer-launch" var queryItems: [URLQueryItem] = [] if let bundlePath = self.appInfo.relativeBundlePath { queryItems.append(URLQueryItem(name: "bundle-name", value: bundlePath)) } if let folderName = uiSelectedContainer?.folderName { queryItems.append(URLQueryItem(name: "container-folder-name", value: folderName)) } launchURLComp.queryItems = queryItems if let url = launchURLComp.url { await UIApplication.shared.open(url) } else { throw "Unable to build URL from launchURLComp???" } return } } guard let ans = await delegate?.showRunWhenMultitaskAlert(), ans else { return } } await MainActor.run { isAppRunning = true } defer { Task { await MainActor.run { isAppRunning = false }} } try await signApp(force: false) if let bundleIdOverride { UserDefaults.standard.set(bundleIdOverride, forKey: "selected") } else { UserDefaults.standard.set(self.appInfo.relativeBundlePath, forKey: "selected") } if let urlStr { UserDefaults.standard.setValue(urlStr, forKey: "launchAppUrlScheme") } UserDefaults.standard.set(uiSelectedContainer?.folderName, forKey: "selectedContainer") // Expose per-app JIT settings so the JIT delegate can read pairing file + VPN. UserDefaults.standard.set(uiPairingFilePath, forKey: "LCJITPairingFilePath") UserDefaults.standard.set(uiWaitForVPN, forKey: "LCJITWaitForVPN") // Per-app JIT: use uiIsJITEnabled when set; otherwise fall back to isJITNeeded/is32bit. var jitNeeded = uiIsJITEnabled ? true : (appInfo.isJITNeeded || appInfo.is32bit) if let forceJIT { jitNeeded = forceJIT } #if targetEnvironment(simulator) jitNeeded = false #endif if jitNeeded { if multitask, #available(iOS 17.4, *) { try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in LCUtils.launchMultitaskGuestApp(appInfo.displayName()) { pidNumber, error in if let error { continuation.resume(throwing: error) return } guard let pidNumber = pidNumber else { continuation.resume(throwing: "Failed to obtain PID from LiveProcess") return } Task { let scriptData = jitLaunchScriptJs ?? appInfo.jitLaunchScriptJs if !scriptData.isEmpty { await self.delegate?.jitLaunch(withPID: pidNumber.intValue, withScript: scriptData, appName: self.appInfo.displayName()) } else { await self.delegate?.jitLaunch(withPID: pidNumber.intValue, withScript: nil, appName: self.appInfo.displayName()) } continuation.resume() } } } } else { // Non-multitask JIT flow — pairing file path and waitForVPN are in UserDefaults for the delegate. let scriptData = jitLaunchScriptJs ?? appInfo.jitLaunchScriptJs if !scriptData.isEmpty { await delegate?.jitLaunch(withScript: scriptData, appName: self.appInfo.displayName(), classicMode: classicMode) } else { await delegate?.jitLaunch(appName: self.appInfo.displayName(), classicMode: classicMode) } } } else if multitask, #available(iOS 16.0, *) { try await LCUtils.launchMultitaskGuestApp(appInfo.displayName()) } else { if #available(iOS 26.0, *), FileManager.default.fileExists(atPath: "\(appInfo.bundlePath()!)/Frameworks/MetalANGLE.framework/MetalANGLE") { let fileContents = "\(appInfo.bundlePath()!)/Frameworks/MetalANGLE.framework/MetalANGLE".data(using: .utf8) let fileURL = FileManager.default.urls(for: .libraryDirectory, in: .userDomainMask)[0].appendingPathComponent("preloadLibraries.txt") try fileContents?.write(to: fileURL) } LCSharedUtils.launchToGuestApp(withClassicMode: classicMode) } // Record the launch time and increment launch count appInfo.lastLaunched = Date() appInfo.launchCount = appInfo.launchCount + 1 appInfo.save() await MainActor.run { isAppRunning = false } } /// Launch multiple apps concurrently for faster startup. /// Returns a dictionary mapping each app’s bundle path to its launch result. static func launchMultiple(_ apps: [LCAppModel]) async -> [String: Result<Void, Error>] { var results: [String: Result<Void, Error>] = [:] await withTaskGroup(of: (String, Result<Void, Error>).self) { group in for app in apps { group.addTask { let key = app.appInfo.relativeBundlePath ?? app.displayName do { try await app.runApp() return (key, .success(())) } catch { return (key, .failure(error)) } } } for await (key, result) in group { results[key] = result } } return results } /// Faster launch path for home screen shortcuts — skips re-signing and /// multitask checks, goes straight to launching the guest app. /// Assumes the app is already signed (which it is after installation). /// Uses per-app JIT settings (isJITEnabled, pairingFilePath, waitForVPN). func fastLaunch() async throws { if isAppRunning { return } // Ensure a container exists if uiContainers.isEmpty { let newName = NSUUID().uuidString let newContainer = LCContainer(folderName: newName, name: newName, isShared: uiIsShared) uiContainers.append(newContainer) uiSelectedContainer = newContainer appInfo.containers = uiContainers newContainer.makeLCContainerInfoPlist(appIdentifier: appInfo.bundleIdentifier()!, keychainGroupId: Int.random(in: 0..<SharedModel.keychainAccessGroupCount)) appInfo.dataUUID = newName uiDefaultDataFolder = newName } let classicMode = appInfo.defaultClassicMode await MainActor.run { isAppRunning = true } defer { Task { await MainActor.run { isAppRunning = false }} } // Skip re-signing — app is already signed after installation UserDefaults.standard.set(self.appInfo.relativeBundlePath, forKey: "selected") UserDefaults.standard.set(uiSelectedContainer?.folderName, forKey: "selectedContainer") // Expose per-app JIT settings so the JIT delegate can read pairing file + VPN. UserDefaults.standard.set(uiPairingFilePath, forKey: "LCJITPairingFilePath") UserDefaults.standard.set(uiWaitForVPN, forKey: "LCJITWaitForVPN") // Per-app JIT: honor uiIsJITEnabled even for shortcut launches. var jitNeeded = uiIsJITEnabled ? true : (appInfo.isJITNeeded || appInfo.is32bit) #if targetEnvironment(simulator) jitNeeded = false #endif if jitNeeded { let scriptData = jitLaunchScriptJs ?? appInfo.jitLaunchScriptJs if !scriptData.isEmpty { await delegate?.jitLaunch(withScript: scriptData, appName: self.appInfo.displayName(), classicMode: classicMode) } else { await delegate?.jitLaunch(appName: self.appInfo.displayName(), classicMode: classicMode) } } else { if #available(iOS 26.0, *), FileManager.default.fileExists(atPath: "\(appInfo.bundlePath()!)/Frameworks/MetalANGLE.framework/MetalANGLE") { let fileContents = "\(appInfo.bundlePath()!)/Frameworks/MetalANGLE.framework/MetalANGLE".data(using: .utf8) let fileURL = FileManager.default.urls(for: .libraryDirectory, in: .userDomainMask)[0].appendingPathComponent("preloadLibraries.txt") try fileContents?.write(to: fileURL) } LCSharedUtils.launchToGuestApp(withClassicMode: classicMode) } appInfo.lastLaunched = Date() appInfo.launchCount = appInfo.launchCount + 1 appInfo.save() } /// Toggle favorite state for this app. Favorites can be pinned to the top of app lists. func toggleFavorite() { appInfo.isFavorite.toggle() appInfo.save() } var isFavorite: Bool { get { appInfo.isFavorite } set { appInfo.isFavorite = newValue } } var launchCount: Int { Int(appInfo.launchCount) } func forceResign() async throws { if isAppRunning { return } isAppRunning = true defer { Task{ await MainActor.run { self.isAppRunning = false }} } try await signApp(force: true) } func signApp(force: Bool = false) async throws { var signError : String? = nil var signSuccess = false defer { Task{ await MainActor.run { self.isSigningInProgress = false }} } await withUnsafeContinuation({ c in appInfo.patchExecAndSignIfNeed(completionHandler: { success, error in signError = error; signSuccess = success; c.resume() }, progressHandler: { signProgress in guard let signProgress else { return } self.isSigningInProgress = true self.observer = signProgress.observe(\.fractionCompleted) { p, v in DispatchQueue.main.async { self.signProgress = signProgress.fractionCompleted } } }, forceSign: force) }) if let signError { if !signSuccess { throw signError.loc } } // sign its tweak guard let tweakFolder = appInfo.tweakFolder else { return } let tweakFolderUrl : URL if(appInfo.isShared) { tweakFolderUrl = LCPath.lcGroupTweakPath.appendingPathComponent(tweakFolder) } else { tweakFolderUrl = LCPath.tweakPath.appendingPathComponent(tweakFolder) } try await LCUtils.signTweaks(tweakFolderUrl: tweakFolderUrl, force: force) { p in Task{ await MainActor.run { self.isSigningInProgress = true }} } // sign global tweak try await LCUtils.signTweaks(tweakFolderUrl: LCPath.tweakPath, force: force) { p in Task{ await MainActor.run { self.isSigningInProgress = true }} } } func setLocked(newLockState: Bool) async { // if locked state in appinfo already match with the new state, we just the change if appInfo.isLocked == newLockState { return } if newLockState { appInfo.isLocked = true } else { // authenticate before cancelling locked state do { let result = try await LCUtils.authenticateUser() if !result { uiIsLocked = true return } } catch { uiIsLocked = true return } // auth pass, we need to cancel app’s lock and hidden state appInfo.isLocked = false if appInfo.isHidden { await toggleHidden() } } } func toggleHidden() async { delegate?.closeNavigationView() if appInfo.isHidden { appInfo.isHidden = false uiIsHidden = false } else { appInfo.isHidden = true uiIsHidden = true } delegate?.changeAppVisibility(app: self) } func loadSupportedLanguages() throws { let fm = FileManager.default if supportedLanguages != nil { return } supportedLanguages = [] let fileURLs = try fm.contentsOfDirectory(at: URL(fileURLWithPath: appInfo.bundlePath()!) , includingPropertiesForKeys: nil) for fileURL in fileURLs { let attributes = try fm.attributesOfItem(atPath: fileURL.path) let fileType = attributes[.type] as? FileAttributeType if(fileType == .typeDirectory && fileURL.lastPathComponent.hasSuffix(".lproj")) { supportedLanguages?.append(fileURL.deletingPathExtension().lastPathComponent) } } } private func bringExistingMultitaskWindowIfNeeded(dataUUID: String, urlScheme: String?) async -> Bool { guard #available(iOS 16.0, *) else { return false } return await MainActor.run { if let urlScheme { UserDefaults.standard.setValue(urlScheme, forKey: "launchAppUrlScheme") } var found = false if #available(iOS 16.1, *) { found = MultitaskWindowManager.openExistingAppWindow(dataUUID: dataUUID) } if !found { found = MultitaskDockManager.shared.bringMultitaskViewToFront(uuid: dataUUID) } if let urlScheme, !found { UserDefaults.standard.removeObject(forKey: "launchAppUrlScheme") } return found } } static func copy(fromApp: LCAppModel, toAppInfo: LCAppInfo) { // copy previous configration to new app toAppInfo.autoSaveDisabled = true toAppInfo.isLocked = fromApp.appInfo.isLocked toAppInfo.isHidden = fromApp.appInfo.isHidden toAppInfo.isShared = fromApp.appInfo.isShared toAppInfo.containerInfo = fromApp.appInfo.containerInfo toAppInfo.tweakFolder = fromApp.appInfo.tweakFolder toAppInfo.dataUUID = fromApp.appInfo.dataUUID toAppInfo.spoofSDKVersion = fromApp.appInfo.spoofSDKVersion toAppInfo.doSymlinkInbox = fromApp.appInfo.doSymlinkInbox toAppInfo.selectedLanguage = fromApp.appInfo.selectedLanguage toAppInfo.orientationLock = fromApp.appInfo.orientationLock toAppInfo.dontInjectTweakLoader = fromApp.appInfo.dontInjectTweakLoader toAppInfo.hideLiveContainer = fromApp.appInfo.hideLiveContainer toAppInfo.dontLoadTweakLoader = fromApp.appInfo.dontLoadTweakLoader toAppInfo.doUseLCBundleId = fromApp.appInfo.doUseLCBundleId toAppInfo.fixFilePickerNew = fromApp.appInfo.fixFilePickerNew toAppInfo.fixLocalNotification = fromApp.appInfo.fixLocalNotification toAppInfo.fixBackgroundTaskIdentifiers = fromApp.appInfo.fixBackgroundTaskIdentifiers toAppInfo.isJITNeeded = fromApp.appInfo.isJITNeeded toAppInfo.isJITEnabled = fromApp.appInfo.isJITEnabled toAppInfo.waitForVPN = fromApp.appInfo.waitForVPN toAppInfo.pairingFilePath = fromApp.appInfo.pairingFilePath toAppInfo.jitLaunchScriptJs = fromApp.appInfo.jitLaunchScriptJs toAppInfo.helperProcessesSupport = fromApp.appInfo.helperProcessesSupport toAppInfo.multitaskSpecified = fromApp.appInfo.multitaskSpecified toAppInfo.classicMode = fromApp.appInfo.classicMode toAppInfo.lastLaunched = fromApp.appInfo.lastLaunched toAppInfo.launchCount = fromApp.appInfo.launchCount toAppInfo.isFavorite = fromApp.appInfo.isFavorite toAppInfo.autoSaveDisabled = false toAppInfo.save() } }